/** Report consumer errors without interrupting bridge operations or other listeners. */
export function notifyListener(listener) {
    try {
        listener();
    }
    catch (error) {
        if (typeof globalThis.reportError === "function") {
            globalThis.reportError(error);
        }
        else {
            setTimeout(() => {
                throw error;
            }, 0);
        }
    }
}
